<!doctype html><html lang="sr"><head><meta charset="utf-8"><style>@page{margin:0}*{box-sizing:border-box}body{margin:0;color:#0f172a;font-family:DejaVu Sans Mono,monospace;font-size:8pt}.p{padding:14mm 16mm 18mm}.packet{border:2px solid #0ea5e9}.bar{padding:4mm 6mm;background:#e0f2fe;color:#0369a1;font-weight:bold}.head{padding:7mm}.t,.items,.sum{width:100%;border-collapse:collapse}.t td{padding:5px;border:1px solid #bae6fd;vertical-align:top}.key{color:#0284c7}.items{margin-top:6mm}.items th{padding:6px;background:#0f172a;color:#fff;text-align:left}.items td{padding:7px;border-bottom:1px solid #bae6fd}.r{text-align:right}.sum{width:46%;margin:7mm 0 0 auto;border:1px solid #0ea5e9}.sum td{padding:6px;border-top:1px solid #bae6fd}.sum td:last-child{text-align:right;font-weight:bold}.total td{background:#0ea5e9;color:#fff;font-size:11pt}.payload{margin-top:7mm;padding:7px;background:#f0f9ff;border:1px dashed #0ea5e9;white-space:pre-line}.foot{position:fixed;bottom:7mm;left:16mm;color:#94a3b8;font-size:6pt}</style></head><body><div class="p"><div class="packet"><div class="bar">PACKET / INVOICE · checksum {{ $invoice->invoice_number }}</div><div class="head"><table class="t"><tr><td><span class="key">source:</span><br><strong>{{ $company->name }}</strong><br>{{ $company->city }}</td><td><span class="key">destination:</span><br><strong>{{ $invoice->client?->name }}</strong><br>{{ $invoice->client?->city }}</td></tr><tr><td><span class="key">protocol:</span> {{ $invoice->payment_type?->label() }}</td><td><span class="key">timestamp:</span> {{ $invoice->date?->format('d.m.Y.') }}</td></tr></table><table class="items"><thead><tr><th>payload</th><th class="r">qty</th><th class="r">value</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->name }}</td><td class="r">{{ $item->quantity }} {{ $item->unit?->value }}</td><td class="r">{{ $f($item->total) }} {{ $c }}</td></tr>@endforeach</tbody></table><table class="sum"><tr><td>base</td><td>{{ $f($invoice->